/* NavLink accent for consistency, matches App.js accent */
.nav-link {
  color: #fff;
  text-decoration: none;
  padding: 8px 0;
  margin: 0 8px;
  font-size: 1rem;
  font-weight: 500;
  border-bottom: 2px solid transparent;
  transition: color .2s, border-bottom .2s;
}
.nav-link:visited {
  color: #fff;
}
.nav-link:hover {
  color: var(--accent);
  border-bottom: 2px solid var(--accent);
}
.active-nav-link {
  color: var(--accent) !important;
  border-bottom: 2px solid var(--accent) !important;
}

/* Feature container for immersive look */
.feature-page {
  min-height: 60vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  color: #fff;
  background: linear-gradient(120deg, #101010 40%, #434343 100%);
  border-radius: 22px;
  box-shadow: 0 7px 26px 0 rgba(0,0,0,0.13);
  margin: 28px 0 24px 0;
  padding: 54px 20px 48px 20px;
  animation: fade-in 0.6s;
  border: 1.5px solid var(--border-color);
}

@keyframes fade-in {
  from { opacity: 0; transform: translateY(32px);}
  to { opacity: 1; transform: translateY(0);}
}
